/**
 * Fields the engine mounts on `ctx` that the published SDK types do not carry
 * yet. Declared here so this plugin typechecks on its own; drop the entry once
 * the corresponding SDK release adds it.
 *
 * `artifacts` is the engine-owned handoff of generated bytes between two tools
 * of the same conversation: another plugin renders a PDF and hands back a
 * handle, `file` consumes it. Neither plugin can import the other, and the
 * bytes must never travel through the model.
 */
import "@polyant-ai/plugin-sdk";

declare module "@polyant-ai/plugin-sdk" {
  interface ToolContext {
    memoryScopeKey: string;
    artifacts: {
      put(
        payload: { buffer: Buffer; filename: string; mime: string },
        ttlMs?: number,
      ): string;
      take(
        handle: string,
      ): { buffer: Buffer; filename: string; mime: string } | null;
    };
  }
}
